import{_ as a,o as t,c as s,a5 as r}from"./chunks/framework.DrDMl0tG.js";const i="/assets/mjcf_gymnasium_walker2d.BThfb1pW.png",p=JSON.parse('{"title":"Server Example: MJCF Gymnasium Walker2d","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/mjcf_gymnasium_walker2d.md","filePath":"sections/examples/server/mjcf_gymnasium_walker2d.md"}'),o={name:"sections/examples/server/mjcf_gymnasium_walker2d.md"};function l(n,e,d,m,c,u){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="server-example-mjcf-gymnasium-walker2d" tabindex="-1">Server Example: MJCF Gymnasium Walker2d <a class="header-anchor" href="#server-example-mjcf-gymnasium-walker2d" aria-label="Permalink to &quot;Server Example: MJCF Gymnasium Walker2d&quot;">​</a></h1><p><img src="'+i+'" alt="mjcf_gymnasium_walker2d example"></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Loads the Gymnasium Walker2d MuJoCo XML asset through <code>raisim::World</code> and publishes it through <code>raisim::RaisimServer</code>. Its links touch the floor but not each other, as in MuJoCo: their geoms have <code>conaffinity=&quot;0&quot;</code> and the floor <code>conaffinity=&quot;1&quot;</code>.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>mjcf_gymnasium_walker2d</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/mjcf_gymnasium_walker2d</span></span></code></pre></div><p>On Windows, run <code>mjcf_gymnasium_walker2d.exe</code> instead. This example uses RaisimServer. Start <code>rayrai_tcp_viewer</code> and connect to port 8080.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Loads <code>rsc/mjcf/gymnasium/walker2d.xml</code> with the <code>raisim::World</code> constructor and retrieves the articulated system by its root body name (<code>torso</code>).</li><li>Handles a multi-link MJCF articulated system with contact-enabled geoms.</li><li>Applies a small sinusoidal torque pattern to the non-root joints in <code>FORCE_AND_TORQUE</code> control mode.</li></ul>',12)])])}const _=a(o,[["render",l]]);export{p as __pageData,_ as default};
